import Component from 'flarum/common/Component';
import app from 'flarum/forum/app';
import extractText from 'flarum/common/utils/extractText';
import ShowcaseCard from './ShowcaseCard';
export default class ShowcaseCarousel extends Component {
  trackEl = null;
  oncreate(vnode) {
    super.oncreate(vnode);
    this.trackEl = vnode.dom.querySelector('.ShowcaseCarousel-track');
  }
  scroll(dir) {
    if (!this.trackEl) return;
    const firstCard = this.trackEl.querySelector('.ShowcaseCard');
    const step = firstCard ? firstCard.getBoundingClientRect().width + 14 : 300;
    this.trackEl.scrollBy({
      left: dir * step * 2,
      behavior: 'smooth'
    });
  }
  view() {
    const prevLabel = extractText(app.translator.trans('ernestdefoe-showcase.lib.carousel.previous'));
    const nextLabel = extractText(app.translator.trans('ernestdefoe-showcase.lib.carousel.next'));
    return m("div", {
      className: "ShowcaseCarousel"
    }, m("button", {
      type: "button",
      className: "ShowcaseCarousel-nav ShowcaseCarousel-nav--prev",
      "aria-label": prevLabel,
      title: prevLabel,
      onclick: () => this.scroll(-1)
    }, "\u2039"), m("button", {
      type: "button",
      className: "ShowcaseCarousel-nav ShowcaseCarousel-nav--next",
      "aria-label": nextLabel,
      title: nextLabel,
      onclick: () => this.scroll(1)
    }, "\u203A"), m("div", {
      className: "ShowcaseCarousel-track"
    }, this.attrs.discussions.map(d => m(ShowcaseCard, {
      key: d.id(),
      discussion: d
    }))));
  }
}
flarum.reg.add('ernestdefoe-showcase', 'forum/components/ShowcaseCarousel', ShowcaseCarousel);