import Component from 'flarum/common/Component';
import ShowcaseCard from './ShowcaseCard';
export default class ShowcaseGrid extends Component {
  view() {
    return m("div", {
      className: "ShowcaseGrid"
    }, this.attrs.discussions.map(d => m(ShowcaseCard, {
      key: d.id(),
      discussion: d
    })));
  }
}
flarum.reg.add('ernestdefoe-showcase', 'forum/components/ShowcaseGrid', ShowcaseGrid);